const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one planner output item, received ${items.length}.`);
}

const input = items[0].json;

const generationRunId =
  input.generation_run_id ??
  input.planning_context?.generation_run_id ??
  null;

const periodId =
  input.period_id ??
  input.planning_context?.period_id ??
  input.planning_context?.period?.id ??
  null;

const planningContext =
  input.planning_context?.context_version === 1
    ? input.planning_context
    : input.planning_context?.planning_context?.context_version === 1
      ? input.planning_context.planning_context
      : input.planning_context ?? null;

const availabilityFacts = input.availability_facts ?? {};
const draftPlan = input.draft_plan ?? null;
const plannerAgentReview = input.planner_agent_review ?? null;
const draftAssignmentsSaveResult = input.draft_assignments_save_result ?? null;

if (!generationRunId) throw new Error("Missing generation_run_id.");
if (!periodId) throw new Error("Missing period_id.");
if (!planningContext || typeof planningContext !== "object") {
  throw new Error("Missing valid planning_context.");
}
if (!draftPlan || typeof draftPlan !== "object") {
  throw new Error("Missing draft_plan.");
}
if (!Array.isArray(draftPlan.assignments)) {
  throw new Error("draft_plan.assignments must be an array.");
}
if (!Array.isArray(draftPlan.unfilled_shifts)) {
  throw new Error("draft_plan.unfilled_shifts must be an array.");
}

const staff = Array.isArray(planningContext.staff) ? planningContext.staff : [];
const shifts = Array.isArray(planningContext.shifts) ? planningContext.shifts : [];
const availabilityDays = Array.isArray(planningContext.availability_days)
  ? planningContext.availability_days
  : [];
const training = Array.isArray(planningContext.training)
  ? planningContext.training
  : [];
const contracts = Array.isArray(planningContext.contracts)
  ? planningContext.contracts
  : [];
const submissions = Array.isArray(planningContext.availability_submissions)
  ? planningContext.availability_submissions
  : [];
const settings = planningContext.settings ?? {};
const period = planningContext.period ?? {};

const assignments = draftPlan.assignments;
const unfilledShifts = draftPlan.unfilled_shifts;
const staffLoadSummary = Array.isArray(draftPlan.staff_load_summary)
  ? draftPlan.staff_load_summary
  : [];

const hardRuleViolations = [];
const softRuleWarnings = [];
const humanReviewFlags = [];

function pushHard(type, message, details = {}) {
  hardRuleViolations.push({
    type,
    severity: "blocking",
    message,
    details,
  });
}

function pushSoft(type, message, details = {}) {
  softRuleWarnings.push({
    type,
    severity: "warning",
    message,
    details,
  });
}

function pushReview(type, message, details = {}) {
  humanReviewFlags.push({
    type,
    severity: details.severity ?? "medium",
    message,
    details,
  });
}

function asDate(dateString) {
  return new Date(`${dateString}T00:00:00Z`);
}

function nextDate(dateString) {
  const date = asDate(dateString);
  date.setUTCDate(date.getUTCDate() + 1);
  return date.toISOString().slice(0, 10);
}

function previousDate(dateString) {
  const date = asDate(dateString);
  date.setUTCDate(date.getUTCDate() - 1);
  return date.toISOString().slice(0, 10);
}

function weekday(dateString) {
  return asDate(dateString).getUTCDay();
}

function isSaturday(dateString) {
  return weekday(dateString) === 6;
}

function isSunday(dateString) {
  return weekday(dateString) === 0;
}

function isoWeekKey(dateString) {
  const date = asDate(dateString);
  const day = date.getUTCDay() || 7;

  date.setUTCDate(date.getUTCDate() + 4 - day);

  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((date - yearStart) / 86400000) + 1) / 7);

  return `${date.getUTCFullYear()}-W${String(weekNo).padStart(2, "0")}`;
}

function staffName(staffId) {
  return staffById.get(staffId)?.full_name ?? staffId;
}

function getTrainingPhase(staffId) {
  const row = trainingByStaffId.get(staffId);

  return (
    row?.phase ??
    row?.training_phase ??
    "phase_3_fully_trained"
  );
}

function isIndependentAssignment(assignment) {
  const kind = assignment.assignment_kind ?? "coverage";

  return ![
    "shadow",
    "training_shadow",
    "supervised_shadow",
  ].includes(kind);
}

function availabilityForShift(day, shiftType) {
  if (!day) return false;

  if (shiftType === "morning") return Boolean(day.morning);
  if (shiftType === "day") return Boolean(day.day);
  if (shiftType === "evening") return Boolean(day.evening);

  return false;
}

function contractForStaff(staffId) {
  return contractsByStaffId.get(staffId)?.[0] ?? null;
}

function longestConsecutiveRun(datesInput) {
  const dates = [...new Set(datesInput)].sort();

  if (dates.length === 0) {
    return {
      longest_streak: 0,
      streak_start: null,
      streak_end: null,
    };
  }

  let streak = 1;
  let longestStreak = 1;
  let streakStart = dates[0];
  let bestStart = dates[0];
  let bestEnd = dates[0];

  for (let i = 1; i < dates.length; i++) {
    if (dates[i] === nextDate(dates[i - 1])) {
      streak += 1;
    } else {
      if (streak > longestStreak) {
        longestStreak = streak;
        bestStart = streakStart;
        bestEnd = dates[i - 1];
      }

      streak = 1;
      streakStart = dates[i];
    }
  }

  if (streak > longestStreak) {
    longestStreak = streak;
    bestStart = streakStart;
    bestEnd = dates[dates.length - 1];
  }

  return {
    longest_streak: longestStreak,
    streak_start: bestStart,
    streak_end: bestEnd,
  };
}

function isolatedWorkingDays(datesInput) {
  const dates = new Set(datesInput);
  const isolated = [];

  for (const date of dates) {
    if (!dates.has(previousDate(date)) && !dates.has(nextDate(date))) {
      isolated.push(date);
    }
  }

  return isolated.sort();
}

const staffById = new Map(staff.map((person) => [person.id, person]));
const shiftById = new Map(shifts.map((shift) => [shift.id, shift]));
const trainingByStaffId = new Map(training.map((row) => [row.staff_id, row]));
const submissionsByStaffId = new Map(submissions.map((row) => [row.staff_id, row]));
const loadByStaffId = new Map(staffLoadSummary.map((row) => [row.staff_id, row]));

const contractsByStaffId = new Map();

for (const contract of contracts) {
  if (!contract.staff_id) continue;

  if (!contractsByStaffId.has(contract.staff_id)) {
    contractsByStaffId.set(contract.staff_id, []);
  }

  contractsByStaffId.get(contract.staff_id).push(contract);
}

const availabilityByStaffDate = new Map();

for (const day of availabilityDays) {
  if (!day.staff_id || !day.available_date) continue;
  availabilityByStaffDate.set(`${day.staff_id}:${day.available_date}`, day);
}

const assignmentsByShiftId = new Map();
const assignmentsByStaffDate = new Map();
const assignmentsByStaffWeek = new Map();
const assignedDatesByStaff = new Map();
const shiftTypesByStaffDate = new Map();

for (const assignment of assignments) {
  const shiftId = assignment.shift_id;
  const staffId = assignment.staff_id;
  const shiftDate = assignment.shift_date;
  const shiftType = assignment.shift_type;

  if (!shiftId) {
    pushHard("assignment_missing_shift_id", "Assignment is missing shift_id.", { assignment });
    continue;
  }

  if (!staffId) {
    pushHard("assignment_missing_staff_id", "Assignment is missing staff_id.", { assignment });
    continue;
  }

  if (!shiftDate) {
    pushHard("assignment_missing_shift_date", "Assignment is missing shift_date.", { assignment });
    continue;
  }

  if (!shiftType) {
    pushHard("assignment_missing_shift_type", "Assignment is missing shift_type.", { assignment });
    continue;
  }

  if (!staffById.has(staffId)) {
    pushHard("unknown_staff_assignment", "Assignment uses an unknown staff member.", {
      staff_id: staffId,
      shift_id: shiftId,
    });
  }

  if (!shiftById.has(shiftId)) {
    pushHard("unknown_shift_assignment", "Assignment uses an unknown shift.", {
      staff_id: staffId,
      shift_id: shiftId,
    });
  }

  if (!assignmentsByShiftId.has(shiftId)) assignmentsByShiftId.set(shiftId, []);
  assignmentsByShiftId.get(shiftId).push(assignment);

  const staffDateKey = `${staffId}:${shiftDate}`;
  const staffWeekKey = `${staffId}:${isoWeekKey(shiftDate)}`;

  if (!assignmentsByStaffDate.has(staffDateKey)) assignmentsByStaffDate.set(staffDateKey, []);
  assignmentsByStaffDate.get(staffDateKey).push(assignment);

  if (!assignmentsByStaffWeek.has(staffWeekKey)) assignmentsByStaffWeek.set(staffWeekKey, []);
  assignmentsByStaffWeek.get(staffWeekKey).push(assignment);

  if (!assignedDatesByStaff.has(staffId)) assignedDatesByStaff.set(staffId, new Set());
  assignedDatesByStaff.get(staffId).add(shiftDate);

  if (!shiftTypesByStaffDate.has(staffDateKey)) shiftTypesByStaffDate.set(staffDateKey, new Set());
  shiftTypesByStaffDate.get(staffDateKey).add(shiftType);

  const availabilityDay = availabilityByStaffDate.get(staffDateKey);

  if (!availabilityForShift(availabilityDay, shiftType)) {
    pushHard("assigned_when_unavailable", `${staffName(staffId)} is assigned when unavailable.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      shift_id: shiftId,
      shift_date: shiftDate,
      shift_type: shiftType,
    });
  }

  const trainingPhase = getTrainingPhase(staffId);

  if (
    isIndependentAssignment(assignment) &&
    trainingPhase === "phase_1_shadow_only"
  ) {
    pushHard("phase_1_independent_assignment", "Phase 1 trainee is assigned as independent coverage.", {
      staff_id: staffId,
      staff_name: staffName(staffId),
      shift_id: shiftId,
      shift_date: shiftDate,
      shift_type: shiftType,
      training_phase: trainingPhase,
      assignment_kind: assignment.assignment_kind ?? "coverage",
    });
  }
}

/**
 * Required coverage check.
 * Avoid double-counting planner-declared unfilled shifts as separate hard errors.
 */
const underfilledShiftIds = new Set();

for (const shift of shifts) {
  const requiredCount = Number(shift.required_count ?? 1);
  const assignedToShift = assignmentsByShiftId.get(shift.id) ?? [];

  const independentAssignedCount = assignedToShift.filter((assignment) =>
    isIndependentAssignment(assignment)
  ).length;

  if (!shift.is_optional && independentAssignedCount < requiredCount) {
    underfilledShiftIds.add(shift.id);

    pushHard("mandatory_shift_underfilled", "Mandatory shift does not meet required coverage.", {
      shift_id: shift.id,
      shift_date: shift.shift_date,
      shift_type: shift.shift_type,
      required_count: requiredCount,
      assigned_count: independentAssignedCount,
      missing_count: requiredCount - independentAssignedCount,
    });
  }

  if (shift.is_optional && independentAssignedCount < requiredCount) {
    pushSoft("optional_shift_underfilled", "Optional shift does not meet desired coverage.", {
      shift_id: shift.id,
      shift_date: shift.shift_date,
      shift_type: shift.shift_type,
      required_count: requiredCount,
      assigned_count: independentAssignedCount,
      missing_count: requiredCount - independentAssignedCount,
    });
  }
}

/**
 * Keep explicit unfilled shifts as human review context instead of duplicate blocking errors.
 */
for (const unfilled of unfilledShifts) {
  const missingCount = Number(unfilled.missing_count ?? 0);
  if (missingCount <= 0) continue;

  pushReview("planner_declared_unfilled_shift", "Planner left this shift unfilled.", {
    severity: "high",
    shift_id: unfilled.shift_id,
    shift_date: unfilled.shift_date,
    shift_type: unfilled.shift_type,
    required_count: unfilled.required_count,
    assigned_count: unfilled.assigned_count,
    missing_count: missingCount,
    reason: unfilled.reason,
  });
}

/**
 * Same-day duplicate assignment.
 */
for (const [staffDateKey, dayAssignments] of assignmentsByStaffDate.entries()) {
  if (dayAssignments.length <= 1) continue;

  const [staffId, shiftDate] = staffDateKey.split(":");

  pushHard("same_day_duplicate_assignment", `${staffName(staffId)} is assigned more than once on the same day.`, {
    staff_id: staffId,
    staff_name: staffName(staffId),
    shift_date: shiftDate,
    assignments: dayAssignments.map((assignment) => ({
      shift_id: assignment.shift_id,
      shift_type: assignment.shift_type,
      assignment_kind: assignment.assignment_kind,
    })),
  });
}

/**
 * Evening → next morning rest.
 */
if (settings.block_evening_to_next_morning !== false) {
  for (const [staffDateKey, shiftTypes] of shiftTypesByStaffDate.entries()) {
    const [staffId, shiftDate] = staffDateKey.split(":");

    if (!shiftTypes.has("evening")) continue;

    const nextMorningKey = `${staffId}:${nextDate(shiftDate)}`;
    const nextMorningTypes = shiftTypesByStaffDate.get(nextMorningKey);

    if (nextMorningTypes?.has("morning")) {
      pushHard("evening_to_next_morning_violation", `${staffName(staffId)} is assigned evening then next-morning.`, {
        staff_id: staffId,
        staff_name: staffName(staffId),
        evening_date: shiftDate,
        morning_date: nextDate(shiftDate),
      });
    }
  }
}

/**
 * Phase 2 closing rule.
 */
for (const [shiftId, shiftAssignments] of assignmentsByShiftId.entries()) {
  const shift = shiftById.get(shiftId);
  if (!shift || shift.shift_type !== "evening") continue;

  const independentAssignments = shiftAssignments.filter((assignment) =>
    isIndependentAssignment(assignment)
  );

  const hasPhase3 = independentAssignments.some((assignment) =>
    getTrainingPhase(assignment.staff_id) === "phase_3_fully_trained"
  );

  for (const assignment of independentAssignments) {
    const phase = getTrainingPhase(assignment.staff_id);

    if (phase === "phase_2_opening_independent" && !hasPhase3) {
      pushHard("phase_2_closing_alone", "Phase 2 staff member is assigned to evening/closing without Phase 3 coverage.", {
        staff_id: assignment.staff_id,
        staff_name: staffName(assignment.staff_id),
        shift_id: shiftId,
        shift_date: shift.shift_date,
        shift_type: shift.shift_type,
        training_phase: phase,
      });
    }
  }
}

/**
 * Core Team full weekend rule.
 * This remains a default block for auto-assignment, but repair step can suggest asking as an exception.
 */
const weekendByStaffWeek = new Map();

for (const assignment of assignments) {
  const staffId = assignment.staff_id;
  const shiftDate = assignment.shift_date;
  const person = staffById.get(staffId);

  if (!person || !shiftDate) continue;

  const schedulingRuleRole = person.scheduling_rule_role ?? person.work_role ?? null;

  if (schedulingRuleRole !== "core_team") continue;
  if (!isSaturday(shiftDate) && !isSunday(shiftDate)) continue;

  const key = `${staffId}:${isoWeekKey(shiftDate)}`;

  if (!weekendByStaffWeek.has(key)) {
    weekendByStaffWeek.set(key, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      week: isoWeekKey(shiftDate),
      saturday: false,
      sunday: false,
      dates: [],
    });
  }

  const record = weekendByStaffWeek.get(key);

  if (isSaturday(shiftDate)) record.saturday = true;
  if (isSunday(shiftDate)) record.sunday = true;

  record.dates.push(shiftDate);
}

for (const record of weekendByStaffWeek.values()) {
  if (record.saturday && record.sunday) {
    pushHard("core_team_full_weekend_violation", "Core Team scheduling-rule staff member is assigned both Saturday and Sunday.", {
      staff_id: record.staff_id,
      staff_name: record.staff_name,
      week: record.week,
      dates: [...new Set(record.dates)].sort(),
      note: "Avoid by default. Manager may ask as an exception if coverage requires it.",
    });
  }
}

/**
 * Consecutive day and fragmented pattern checks.
 */
const hardMaxConsecutiveDays = Number(settings.default_hard_max_consecutive_days ?? 5);
const softMaxConsecutiveDays = Number(settings.default_soft_max_consecutive_days ?? 4);

for (const [staffId, dateSet] of assignedDatesByStaff.entries()) {
  const dates = [...dateSet].sort();
  const consecutive = longestConsecutiveRun(dates);

  if (consecutive.longest_streak > hardMaxConsecutiveDays) {
    pushHard("hard_max_consecutive_days_exceeded", `${staffName(staffId)} exceeds hard max consecutive working days.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      ...consecutive,
      hard_max_consecutive_days: hardMaxConsecutiveDays,
    });
  } else if (consecutive.longest_streak > softMaxConsecutiveDays) {
    pushSoft("soft_max_consecutive_days_exceeded", `${staffName(staffId)} exceeds preferred max consecutive working days.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      ...consecutive,
      soft_max_consecutive_days: softMaxConsecutiveDays,
    });
  }

  const isolated = isolatedWorkingDays(dates);

  if (isolated.length >= 2) {
    pushSoft("fragmented_work_pattern", `${staffName(staffId)} has a fragmented work pattern with several isolated working days.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      isolated_working_dates: isolated,
      note: "Where rules allow, prefer grouped/consecutive working days over work-off-work-off patterns.",
    });
  }
}

/**
 * Weekly contract max and weekly minimum warnings.
 */
const weeksInPeriod = [...new Set(shifts.map((shift) => isoWeekKey(shift.shift_date)))].sort();

for (const person of staff) {
  const staffId = person.id;
  const contract = contractForStaff(staffId);
  const phase = getTrainingPhase(staffId);

  if (!contract) continue;

  const weeklyMin = Number(contract.min_shifts_per_week ?? NaN);
  const weeklyMax = Number(contract.max_shifts_per_week ?? NaN);

  for (const week of weeksInPeriod) {
    const weekAssignments = assignmentsByStaffWeek.get(`${staffId}:${week}`) ?? [];
    const assignedCount = weekAssignments.length;

    if (Number.isFinite(weeklyMax) && assignedCount > weeklyMax) {
      pushHard("weekly_max_shifts_exceeded", `${staffName(staffId)} exceeds weekly max shifts.`, {
        staff_id: staffId,
        staff_name: staffName(staffId),
        week,
        assigned_shift_count: assignedCount,
        max_shifts_per_week: weeklyMax,
      });
    }

    if (
      Number.isFinite(weeklyMin) &&
      assignedCount < weeklyMin &&
      phase === "phase_3_fully_trained" &&
      ["manager", "core_team"].includes(person.scheduling_rule_role ?? person.work_role)
    ) {
      pushSoft("weekly_minimum_not_met", `${staffName(staffId)} is below weekly minimum/expected load.`, {
        staff_id: staffId,
        staff_name: staffName(staffId),
        week,
        assigned_shift_count: assignedCount,
        min_shifts_per_week: weeklyMin,
        note: "Minimum/target coverage should be considered before leaving shifts uncovered.",
      });
    }
  }
}

/**
 * Period-level target/max/extra consent.
 */
for (const load of staffLoadSummary) {
  const staffId = load.staff_id;
  const assignedCount = Number(load.assigned_shift_count ?? 0);
  const periodTarget = Number(load.period_target_shifts ?? NaN);
  const periodMax = Number(load.period_max_shifts ?? NaN);
  const extraAllowance = Number(load.extra_shift_allowance ?? 0);
  const person = staffById.get(staffId);
  const submission = submissionsByStaffId.get(staffId);

  if (!person) continue;

  if (Number.isFinite(periodMax) && assignedCount > periodMax) {
    pushHard("period_max_shifts_exceeded", `${staffName(staffId)} exceeds period max shifts.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      assigned_shift_count: assignedCount,
      period_max_shifts: periodMax,
      note: "Manager can request consent/override, but this cannot be auto-published.",
    });
  }

  if (
    Number.isFinite(periodTarget) &&
    assignedCount > periodTarget + extraAllowance
  ) {
    pushHard("above_target_without_allowance", `${staffName(staffId)} is assigned above target without enough extra-shift allowance.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      assigned_shift_count: assignedCount,
      period_target_shifts: periodTarget,
      extra_shift_allowance: extraAllowance,
      willing_to_work_above_target: Boolean(submission?.willing_to_work_above_target),
      note: "This should become a consent request, not an automatic assignment.",
    });
  }

  if (Number.isFinite(periodTarget) && assignedCount < periodTarget) {
    pushSoft("below_period_target", `${staffName(staffId)} is below period target.`, {
      staff_id: staffId,
      staff_name: staffName(staffId),
      assigned_shift_count: assignedCount,
      period_target_shifts: periodTarget,
      training_phase: getTrainingPhase(staffId),
      note: "Do not leave staff below target while shifts remain uncovered if they have valid availability/capacity.",
    });
  }
}

/**
 * Budget usage estimate.
 */
let estimatedDraftLaborCost = 0;

for (const assignment of assignments) {
  const person = staffById.get(assignment.staff_id);
  const contract = contractForStaff(assignment.staff_id);

  if (!person) continue;

  const hourlyRate = Number(person.hourly_rate ?? 0);
  const shiftHours = Number(contract?.standard_shift_hours ?? 9);

  estimatedDraftLaborCost += hourlyRate * shiftHours;
}

const monthlyStaffBudget = Number(period.monthly_staff_budget_eur ?? NaN);
const estimatedBudgetRemaining =
  Number.isFinite(monthlyStaffBudget)
    ? monthlyStaffBudget - estimatedDraftLaborCost
    : null;

if (
  Number.isFinite(monthlyStaffBudget) &&
  estimatedBudgetRemaining > 0 &&
  unfilledShifts.length > 0
) {
  pushSoft("budget_capacity_unused_with_unfilled_shifts", "There is still estimated staff budget capacity while shifts remain uncovered.", {
    monthly_staff_budget_eur: monthlyStaffBudget,
    estimated_draft_labor_cost_eur: Number(estimatedDraftLaborCost.toFixed(2)),
    estimated_budget_remaining_eur: Number(estimatedBudgetRemaining.toFixed(2)),
    unfilled_shift_count: unfilledShifts.length,
    note: "Use available staffing budget/contract capacity where reasonable before leaving coverage gaps.",
  });
}

/**
 * Planner agent review.
 */
if (plannerAgentReview?.overall_risk_level) {
  const risk = plannerAgentReview.overall_risk_level;

  if (["medium", "high", "critical"].includes(risk)) {
    pushReview("planner_agent_risk", `Planner Agent Review risk level is ${risk}.`, {
      severity: risk === "critical" ? "critical" : risk === "high" ? "high" : "medium",
      overall_risk_level: risk,
      agent_summary: plannerAgentReview.agent_summary ?? null,
    });
  }
}

if (Array.isArray(plannerAgentReview?.human_review_flags)) {
  for (const flag of plannerAgentReview.human_review_flags) {
    humanReviewFlags.push({
      type: flag.flag_type ?? "planner_agent_human_review_flag",
      severity: flag.severity ?? "medium",
      message: flag.message ?? "Planner Agent requested human review.",
      details: {
        source: "planner_agent_review",
        ...flag,
      },
    });
  }
}

const isValid = hardRuleViolations.length === 0;

const validation = {
  validation_version: "schedule_validation_v1",
  generated_at: new Date().toISOString(),

  is_valid: isValid,
  ready_for_commit: isValid,
  requires_human_review:
    !isValid ||
    softRuleWarnings.length > 0 ||
    humanReviewFlags.length > 0,

  summary: {
    assignment_count: assignments.length,
    unfilled_shift_count: unfilledShifts.length,
    hard_rule_violation_count: hardRuleViolations.length,
    soft_rule_warning_count: softRuleWarnings.length,
    human_review_flag_count: humanReviewFlags.length,
    active_staff_count: staff.length,
    shift_count: shifts.length,

    estimated_draft_labor_cost_eur: Number(estimatedDraftLaborCost.toFixed(2)),
    monthly_staff_budget_eur: Number.isFinite(monthlyStaffBudget) ? monthlyStaffBudget : null,
    estimated_budget_remaining_eur:
      estimatedBudgetRemaining === null
        ? null
        : Number(estimatedBudgetRemaining.toFixed(2)),

    draft_assignments_saved:
      Boolean(input.draft_assignments_saved) ||
      Boolean(draftAssignmentsSaveResult?.inserted_count),
    draft_assignments_inserted_count:
      draftAssignmentsSaveResult?.inserted_count ?? null,
  },

  hard_rule_violations: hardRuleViolations,
  soft_rule_warnings: softRuleWarnings,
  human_review_flags: humanReviewFlags,

  checks_run: [
    "required_input_shape",
    "known_staff_and_shift_ids",
    "staff_availability",
    "mandatory_shift_coverage",
    "planner_declared_unfilled_shifts",
    "same_day_duplicate_assignment",
    "evening_to_next_morning_rest",
    "phase_1_independent_assignment",
    "phase_2_closing_alone",
    "core_team_full_weekend",
    "max_consecutive_days",
    "fragmented_work_patterns",
    "weekly_contract_min_and_max",
    "period_target_and_extra_allowance",
    "budget_usage",
    "planner_agent_review_risk",
  ],
};

return [
  {
    json: {
      generation_run_id: generationRunId,
      period_id: periodId,

      planning_context: planningContext,
      availability_facts: availabilityFacts,
      draft_plan: draftPlan,
      planner_agent_review: plannerAgentReview,
      draft_assignments_save_result: draftAssignmentsSaveResult,

      validation,

      schedule_validation_completed_at: new Date().toISOString(),
    },
  },
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one validated schedule item, received ${items.length}.`);
}

const input = items[0].json;

const generationRunId = input.generation_run_id;
const periodId = input.period_id;
const planningContext = input.planning_context;
const availabilityFacts = input.availability_facts ?? {};
const draftPlan = input.draft_plan;
const plannerAgentReview = input.planner_agent_review ?? {};
const validation = input.validation ?? {};

if (!generationRunId) throw new Error("Missing generation_run_id.");
if (!periodId) throw new Error("Missing period_id.");
if (!planningContext || typeof planningContext !== "object") throw new Error("Missing planning_context.");
if (!draftPlan || typeof draftPlan !== "object") throw new Error("Missing draft_plan.");
if (!Array.isArray(draftPlan.assignments)) throw new Error("draft_plan.assignments must be an array.");
if (!Array.isArray(draftPlan.unfilled_shifts)) throw new Error("draft_plan.unfilled_shifts must be an array.");

const staff = Array.isArray(planningContext.staff) ? planningContext.staff : [];
const shifts = Array.isArray(planningContext.shifts) ? planningContext.shifts : [];
const availabilityDays = Array.isArray(planningContext.availability_days)
  ? planningContext.availability_days
  : [];
const training = Array.isArray(planningContext.training)
  ? planningContext.training
  : [];
const contracts = Array.isArray(planningContext.contracts)
  ? planningContext.contracts
  : [];
const submissions = Array.isArray(planningContext.availability_submissions)
  ? planningContext.availability_submissions
  : [];
const settings = planningContext.settings ?? {};

const assignments = draftPlan.assignments;
const unfilledShifts = draftPlan.unfilled_shifts;
const staffLoadSummary = Array.isArray(draftPlan.staff_load_summary)
  ? draftPlan.staff_load_summary
  : [];

function asDate(dateString) {
  return new Date(`${dateString}T00:00:00Z`);
}

function nextDate(dateString) {
  const date = asDate(dateString);
  date.setUTCDate(date.getUTCDate() + 1);
  return date.toISOString().slice(0, 10);
}

function previousDate(dateString) {
  const date = asDate(dateString);
  date.setUTCDate(date.getUTCDate() - 1);
  return date.toISOString().slice(0, 10);
}

function weekday(dateString) {
  return asDate(dateString).getUTCDay();
}

function isSaturday(dateString) {
  return weekday(dateString) === 6;
}

function isSunday(dateString) {
  return weekday(dateString) === 0;
}

function isWeekend(dateString) {
  return isSaturday(dateString) || isSunday(dateString);
}

function isoWeekKey(dateString) {
  const date = asDate(dateString);
  const day = date.getUTCDay() || 7;

  date.setUTCDate(date.getUTCDate() + 4 - day);

  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((date - yearStart) / 86400000) + 1) / 7);

  return `${date.getUTCFullYear()}-W${String(weekNo).padStart(2, "0")}`;
}

function staffName(staffId) {
  return staffById.get(staffId)?.full_name ?? staffId;
}

function availabilityForShift(day, shiftType) {
  if (!day) return false;

  if (shiftType === "morning") return Boolean(day.morning);
  if (shiftType === "day") return Boolean(day.day);
  if (shiftType === "evening") return Boolean(day.evening);

  return false;
}

function getTrainingPhase(staffId) {
  const row = trainingByStaffId.get(staffId);

  return (
    row?.phase ??
    row?.training_phase ??
    "phase_3_fully_trained"
  );
}

function longestConsecutiveRun(datesInput) {
  const dates = [...new Set(datesInput)].sort();

  if (dates.length === 0) {
    return {
      longest_streak: 0,
      streak_start: null,
      streak_end: null,
    };
  }

  let streak = 1;
  let longestStreak = 1;
  let streakStart = dates[0];
  let bestStart = dates[0];
  let bestEnd = dates[0];

  for (let i = 1; i < dates.length; i++) {
    if (dates[i] === nextDate(dates[i - 1])) {
      streak += 1;
    } else {
      if (streak > longestStreak) {
        longestStreak = streak;
        bestStart = streakStart;
        bestEnd = dates[i - 1];
      }

      streak = 1;
      streakStart = dates[i];
    }
  }

  if (streak > longestStreak) {
    longestStreak = streak;
    bestStart = streakStart;
    bestEnd = dates[dates.length - 1];
  }

  return {
    longest_streak: longestStreak,
    streak_start: bestStart,
    streak_end: bestEnd,
  };
}

const staffById = new Map(staff.map((person) => [person.id, person]));
const shiftById = new Map(shifts.map((shift) => [shift.id, shift]));
const trainingByStaffId = new Map(training.map((row) => [row.staff_id, row]));
const submissionsByStaffId = new Map(submissions.map((row) => [row.staff_id, row]));
const loadByStaffId = new Map(staffLoadSummary.map((row) => [row.staff_id, row]));

const contractsByStaffId = new Map();

for (const contract of contracts) {
  if (!contract.staff_id) continue;

  if (!contractsByStaffId.has(contract.staff_id)) {
    contractsByStaffId.set(contract.staff_id, []);
  }

  contractsByStaffId.get(contract.staff_id).push(contract);
}

const availabilityByStaffDate = new Map();

for (const day of availabilityDays) {
  if (!day.staff_id || !day.available_date) continue;
  availabilityByStaffDate.set(`${day.staff_id}:${day.available_date}`, day);
}

const assignmentsByStaffDate = new Map();
const assignmentsByStaffWeek = new Map();
const shiftTypesByStaffDate = new Map();
const assignedDatesByStaff = new Map();

for (const assignment of assignments) {
  const staffId = assignment.staff_id;
  const shiftDate = assignment.shift_date;
  const shiftType = assignment.shift_type;

  if (!staffId || !shiftDate || !shiftType) continue;

  const staffDateKey = `${staffId}:${shiftDate}`;
  const staffWeekKey = `${staffId}:${isoWeekKey(shiftDate)}`;

  if (!assignmentsByStaffDate.has(staffDateKey)) assignmentsByStaffDate.set(staffDateKey, []);
  assignmentsByStaffDate.get(staffDateKey).push(assignment);

  if (!assignmentsByStaffWeek.has(staffWeekKey)) assignmentsByStaffWeek.set(staffWeekKey, []);
  assignmentsByStaffWeek.get(staffWeekKey).push(assignment);

  if (!shiftTypesByStaffDate.has(staffDateKey)) shiftTypesByStaffDate.set(staffDateKey, new Set());
  shiftTypesByStaffDate.get(staffDateKey).add(shiftType);

  if (!assignedDatesByStaff.has(staffId)) assignedDatesByStaff.set(staffId, new Set());
  assignedDatesByStaff.get(staffId).add(shiftDate);
}

function findStaffByName(name) {
  const normalized = name.toLowerCase();

  return staff.find((person) =>
    String(person.full_name ?? "").toLowerCase() === normalized
  ) ?? null;
}

function getCurrentAssignedCount(staffId) {
  return assignments.filter((assignment) => assignment.staff_id === staffId).length;
}

function contractForStaff(staffId) {
  return contractsByStaffId.get(staffId)?.[0] ?? null;
}

function evaluateCandidateForShift(person, unfilledShift) {
  const staffId = person.id;
  const staffNameValue = person.full_name ?? staffId;
  const shiftId = unfilledShift.shift_id;
  const shift = shiftById.get(shiftId);
  const shiftDate = unfilledShift.shift_date ?? shift?.shift_date;
  const shiftType = unfilledShift.shift_type ?? shift?.shift_type;

  const blockers = [];
  const warnings = [];
  const reasons = [];
  const managerAskReasons = [];

  let score = 100;

  const workRole = person.work_role ?? null;
  const schedulingRuleRole = person.scheduling_rule_role ?? person.work_role ?? null;
  const trainingPhase = getTrainingPhase(staffId);

  const availabilityDay = availabilityByStaffDate.get(`${staffId}:${shiftDate}`);
  const isAvailable = availabilityForShift(availabilityDay, shiftType);

  if (!shift) {
    blockers.push({
      type: "unknown_shift",
      message: "Shift does not exist in planning_context.shifts.",
      overridable_by_manager: false,
    });
  }

  if (!isAvailable) {
    blockers.push({
      type: "not_available",
      message: "Staff member is not currently available for this shift.",
      overridable_by_manager: true,
    });

    managerAskReasons.push("Ask whether availability has changed for this specific shift.");
    score -= 35;
  } else {
    reasons.push("available_for_shift");
    score += 15;
  }

  if (trainingPhase === "phase_1_shadow_only") {
    blockers.push({
      type: "phase_1_not_independent",
      message: "Phase 1 trainee cannot be used as independent coverage.",
      overridable_by_manager: false,
    });

    managerAskReasons.push("Could be added as a shadow/training shift only, not as coverage.");
    score -= 40;
  }

  if (shiftType === "evening" && trainingPhase === "phase_2_opening_independent") {
    blockers.push({
      type: "phase_2_cannot_close_alone",
      message: "Phase 2 staff cannot be used as sole evening/closing coverage.",
      overridable_by_manager: false,
    });

    managerAskReasons.push("Could only work this shift if paired with Phase 3 coverage.");
    score -= 25;
  }

  const sameDayAssignments = assignmentsByStaffDate.get(`${staffId}:${shiftDate}`) ?? [];

  if (sameDayAssignments.length > 0) {
    blockers.push({
      type: "same_day_duplicate",
      message: "Staff member already has another shift on this date.",
      existing_assignments: sameDayAssignments.map((assignment) => ({
        shift_id: assignment.shift_id,
        shift_type: assignment.shift_type,
      })),
      overridable_by_manager: true,
    });

    managerAskReasons.push("Could only work if an existing same-day assignment is swapped or removed.");
    score -= 25;
  }

  if (settings.block_evening_to_next_morning !== false) {
    if (shiftType === "morning") {
      const previousDayTypes = shiftTypesByStaffDate.get(`${staffId}:${previousDate(shiftDate)}`);

      if (previousDayTypes?.has("evening")) {
        blockers.push({
          type: "previous_evening_to_morning",
          message: "Staff member already has an evening shift the previous day.",
          previous_date: previousDate(shiftDate),
          overridable_by_manager: true,
        });

        managerAskReasons.push("Would require swapping the previous evening or approving a rest-rule exception.");
        score -= 20;
      }
    }

    if (shiftType === "evening") {
      const nextDayTypes = shiftTypesByStaffDate.get(`${staffId}:${nextDate(shiftDate)}`);

      if (nextDayTypes?.has("morning")) {
        blockers.push({
          type: "evening_to_next_morning",
          message: "Staff member already has a morning shift the next day.",
          next_date: nextDate(shiftDate),
          overridable_by_manager: true,
        });

        managerAskReasons.push("Would require swapping the next morning or approving a rest-rule exception.");
        score -= 20;
      }
    }
  }

  if (schedulingRuleRole === "core_team" && isWeekend(shiftDate)) {
    const assignedDates = assignedDatesByStaff.get(staffId) ?? new Set();
    const week = isoWeekKey(shiftDate);

    const hasSaturday = [...assignedDates].some((date) =>
      isoWeekKey(date) === week && isSaturday(date)
    );

    const hasSunday = [...assignedDates].some((date) =>
      isoWeekKey(date) === week && isSunday(date)
    );

    const addingSaturday = isSaturday(shiftDate);
    const addingSunday = isSunday(shiftDate);

    if ((addingSaturday && hasSunday) || (addingSunday && hasSaturday)) {
      blockers.push({
        type: "core_team_full_weekend",
        message: "Core-team staff may not work both Saturday and Sunday of the same weekend by default.",
        week,
        overridable_by_manager: true,
      });

      managerAskReasons.push("Ask whether they are willing to work the full weekend as a one-off exception.");
      score -= 18;
    } else {
      warnings.push({
        type: "core_team_weekend",
        message: "Core Team scheduling-rule staff would be used on a weekend.",
      });
      score -= 8;
    }
  }

  const currentDates = assignedDatesByStaff.get(staffId) ?? new Set();
  const datesAfterAdding = new Set(currentDates);
  datesAfterAdding.add(shiftDate);

  const consecutive = longestConsecutiveRun([...datesAfterAdding]);

  const hardMaxConsecutiveDays = Number(settings.default_hard_max_consecutive_days ?? 5);
  const softMaxConsecutiveDays = Number(settings.default_soft_max_consecutive_days ?? 4);

  if (consecutive.longest_streak > hardMaxConsecutiveDays) {
    blockers.push({
      type: "hard_max_consecutive_days",
      message: "Adding this shift would exceed hard max consecutive working days.",
      ...consecutive,
      hard_max_consecutive_days: hardMaxConsecutiveDays,
      overridable_by_manager: false,
    });

    score -= 30;
  } else if (consecutive.longest_streak > softMaxConsecutiveDays) {
    warnings.push({
      type: "soft_max_consecutive_days",
      message: "Adding this shift would exceed preferred max consecutive working days.",
      ...consecutive,
      soft_max_consecutive_days: softMaxConsecutiveDays,
    });

    managerAskReasons.push("This creates a longer consecutive block; allowed only if manager accepts the soft warning.");
    score -= 8;
  } else {
    reasons.push("consecutive_pattern_allowed");
    score += 4;
  }

  const contract = contractForStaff(staffId);

  if (!contract) {
    blockers.push({
      type: "missing_contract",
      message: "Staff member has no contract row.",
      overridable_by_manager: false,
    });

    score -= 50;
  } else {
    const weekKey = `${staffId}:${isoWeekKey(shiftDate)}`;
    const currentWeekAssignments = assignmentsByStaffWeek.get(weekKey) ?? [];
    const weeklyMax = Number(contract.max_shifts_per_week ?? Infinity);

    if (Number.isFinite(weeklyMax) && currentWeekAssignments.length + 1 > weeklyMax) {
      blockers.push({
        type: "weekly_max_exceeded",
        message: "Adding this shift would exceed weekly max shifts.",
        current_week_shift_count: currentWeekAssignments.length,
        proposed_week_shift_count: currentWeekAssignments.length + 1,
        max_shifts_per_week: weeklyMax,
        overridable_by_manager: true,
      });

      managerAskReasons.push("Requires manager approval and explicit staff consent to exceed normal weekly max.");
      score -= 15;
    }

    const weeklyTarget = Number(contract.target_shifts_per_week ?? NaN);
    if (Number.isFinite(weeklyTarget) && currentWeekAssignments.length < weeklyTarget) {
      reasons.push("helps_meet_weekly_target");
      score += 10;
    }
  }

  const load = loadByStaffId.get(staffId);
  const submission = submissionsByStaffId.get(staffId);
  const currentAssignedCount = Number(load?.assigned_shift_count ?? getCurrentAssignedCount(staffId));
  const proposedAssignedCount = currentAssignedCount + 1;

  if (load) {
    const periodTarget = Number(load.period_target_shifts ?? NaN);
    const periodMax = Number(load.period_max_shifts ?? NaN);
    const extraAllowance = Number(load.extra_shift_allowance ?? 0);

    if (Number.isFinite(periodMax) && proposedAssignedCount > periodMax) {
      blockers.push({
        type: "period_max_exceeded",
        message: "Adding this shift would exceed period max shifts.",
        current_assigned_shift_count: currentAssignedCount,
        proposed_assigned_shift_count: proposedAssignedCount,
        period_max_shifts: periodMax,
        overridable_by_manager: true,
      });

      managerAskReasons.push("Requires manager approval and staff consent to exceed normal period max.");
      score -= 15;
    }

    if (
      Number.isFinite(periodTarget) &&
      proposedAssignedCount > periodTarget + extraAllowance
    ) {
      blockers.push({
        type: "above_target_without_allowance",
        message: "Adding this shift would put staff above target without enough extra-shift allowance.",
        current_assigned_shift_count: currentAssignedCount,
        proposed_assigned_shift_count: proposedAssignedCount,
        period_target_shifts: periodTarget,
        extra_shift_allowance: extraAllowance,
        willing_to_work_above_target: Boolean(submission?.willing_to_work_above_target),
        overridable_by_manager: true,
      });

      managerAskReasons.push("Ask whether they consent to one extra shift above target.");
      score -= 10;
    }

    if (Number.isFinite(periodTarget) && currentAssignedCount < periodTarget) {
      reasons.push("below_period_target");
      score += 12;
    }
  } else {
    warnings.push({
      type: "missing_staff_load_summary",
      message: "No staff load summary row found. Period target/max could not be fully checked.",
    });
    score -= 5;
  }

  if (workRole === "host") {
    if (shiftType === "evening") score += 8;
    if (isWeekend(shiftDate)) score += 8;
    reasons.push("host_role_useful_for_evenings_or_weekends");
  }

  if (workRole === "manager") {
    warnings.push({
      type: "manager_used_as_fill_in",
      message: "Manager would be used as fill-in coverage.",
    });

    score -= 12;

    if (isWeekend(shiftDate)) {
      score -= 12;
    }
  }

  if (schedulingRuleRole === "core_team" && isWeekend(shiftDate)) {
    score -= 8;
  }

  score -= currentAssignedCount * 1.5;

  const nonOverridableBlockers = blockers.filter(
    (blocker) => blocker.overridable_by_manager === false
  );

  const onlyManagerOverridable =
    blockers.length > 0 && nonOverridableBlockers.length === 0;

  return {
    staff_id: staffId,
    staff_name: staffNameValue,
    work_role: workRole,
    scheduling_rule_role: schedulingRuleRole,
    training_phase: trainingPhase,

    status:
      blockers.length === 0
        ? "auto_assignable"
        : onlyManagerOverridable
          ? "manager_ask_candidate"
          : "blocked",

    score: Math.round(score),
    current_assigned_shift_count: currentAssignedCount,
    proposed_assigned_shift_count: proposedAssignedCount,

    reasons,
    warnings,
    blockers,
    manager_ask_reasons: [...new Set(managerAskReasons)],
  };
}

function addManagerAskCandidate(list, candidate) {
  const key =
    candidate.staff_id ??
    candidate.candidate_name ??
    `${candidate.candidate_type}:${candidate.reason}`;

  if (list.some((item) => (item.staff_id ?? item.candidate_name ?? `${item.candidate_type}:${item.reason}`) === key)) {
    return;
  }

  list.push(candidate);
}

