function unfilledShiftRecords() {
  const fromDraft = draftPlan.unfilled_shifts.map((unfilled) => ({
    shift_id: unfilled.shift_id,
    shift_date: unfilled.shift_date,
    shift_type: unfilled.shift_type,
    required_count: unfilled.required_count,
    assigned_count: unfilled.assigned_count,
    missing_count: unfilled.missing_count,
    reason: unfilled.reason,
  }));

  const fromValidation = Array.isArray(validation.hard_rule_violations)
    ? validation.hard_rule_violations
        .filter((violation) => violation.type === "mandatory_shift_underfilled")
        .map((violation) => ({
          shift_id: violation.details?.shift_id,
          shift_date: violation.details?.shift_date,
          shift_type: violation.details?.shift_type,
          required_count: violation.details?.required_count,
          assigned_count: violation.details?.assigned_count,
          missing_count: violation.details?.missing_count,
          reason: violation.message,
        }))
    : [];

  const combined = [...fromDraft, ...fromValidation];
  const seen = new Set();
  const result = [];

  for (const record of combined) {
    const key = record.shift_id ?? `${record.shift_date}:${record.shift_type}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(record);
  }

  return result;
}

const repairCandidateGroups = [];

for (const unfilled of unfilledShiftRecords()) {
  const shift = shiftById.get(unfilled.shift_id);

  const shiftDate = unfilled.shift_date ?? shift?.shift_date;
  const shiftType = unfilled.shift_type ?? shift?.shift_type;
  const missingCount = Number(unfilled.missing_count ?? 1);

  const evaluatedCandidates = staff.map((person) =>
    evaluateCandidateForShift(person, {
      ...unfilled,
      shift_date: shiftDate,
      shift_type: shiftType,
    })
  );

  const autoAssignableCandidates = evaluatedCandidates
    .filter((candidate) => candidate.status === "auto_assignable")
    .sort((a, b) => b.score - a.score);

  const managerAskCandidates = [];

  for (const candidate of evaluatedCandidates) {
    if (candidate.status !== "manager_ask_candidate") continue;

    addManagerAskCandidate(managerAskCandidates, {
      candidate_type: "staff_exception_or_consent",
      staff_id: candidate.staff_id,
      staff_name: candidate.staff_name,
      work_role: candidate.work_role,
      scheduling_rule_role: candidate.scheduling_rule_role,
      training_phase: candidate.training_phase,
      reason:
        candidate.manager_ask_reasons[0] ??
        "Ask manager/staff whether this exception is acceptable.",
      manager_ask_reasons: candidate.manager_ask_reasons,
      blockers: candidate.blockers,
      warnings: candidate.warnings,
      score: candidate.score,
      requires_manager_approval: true,
      requires_staff_consent: true,
      can_auto_assign: false,
    });
  }

  addSpecificManagerAsks(
    {
      ...unfilled,
      shift_date: shiftDate,
      shift_type: shiftType,
    },
    managerAskCandidates
  );

  const blockedCandidates = evaluatedCandidates
    .filter((candidate) => candidate.status === "blocked")
    .sort((a, b) => {
      if (a.blockers.length !== b.blockers.length) {
        return a.blockers.length - b.blockers.length;
      }

      return b.score - a.score;
    })
    .slice(0, 8);

  repairCandidateGroups.push({
    shift_id: unfilled.shift_id,
    shift_date: shiftDate,
    shift_type: shiftType,
    required_count: unfilled.required_count,
    assigned_count: unfilled.assigned_count,
    missing_count: missingCount,
    original_reason: unfilled.reason ?? null,

    auto_assignable_candidate_count: autoAssignableCandidates.length,
    manager_ask_candidate_count: managerAskCandidates.length,
    blocked_candidate_count: blockedCandidates.length,

    has_rule_clean_candidate: autoAssignableCandidates.length > 0,
    candidate_count: autoAssignableCandidates.length,

    recommended_candidates: autoAssignableCandidates.slice(0, 5),
    auto_assignable_candidates: autoAssignableCandidates.slice(0, 5),

    manager_ask_candidates: managerAskCandidates
      .sort((a, b) => Number(b.score ?? 0) - Number(a.score ?? 0))
      .slice(0, 8),

    blocked_candidates: blockedCandidates,

    manager_decision_required: true,

    recommendation:
      autoAssignableCandidates.length > 0
        ? "Review auto-assignable candidates before applying. Re-run validation after any draft change."
        : managerAskCandidates.length > 0
          ? "No auto-assignable candidate found. Review manager-ask options such as wildcard support, full-weekend exception, or extra-shift consent."
          : "No auto-assignable or manager-ask candidate found. Manager must adjust availability, targets, training status, or constraints before regenerating.",
  });
}

const groupsWithoutAutoAssignableCandidates = repairCandidateGroups.filter(
  (group) => group.auto_assignable_candidates.length === 0
);

const groupsWithoutAnyManagerAsk = repairCandidateGroups.filter(
  (group) =>
    group.auto_assignable_candidates.length === 0 &&
    group.manager_ask_candidates.length === 0
);

const totalAutoAssignableCandidates = repairCandidateGroups.reduce(
  (sum, group) => sum + group.auto_assignable_candidates.length,
  0
);

const totalManagerAskCandidates = repairCandidateGroups.reduce(
  (sum, group) => sum + group.manager_ask_candidates.length,
  0
);

const repairPlan = {
  repair_version: "repair_candidates_v1",
  generated_at: new Date().toISOString(),

  mode: "candidate_generation_and_manager_asks",
  safe_to_auto_apply: false,
  requires_manager_approval: true,

  summary: {
    unfilled_shift_count: repairCandidateGroups.length,
    repair_candidate_group_count: repairCandidateGroups.length,

    total_auto_assignable_candidate_count: totalAutoAssignableCandidates,
    total_recommended_candidate_count: totalAutoAssignableCandidates,

    total_manager_ask_candidate_count: totalManagerAskCandidates,

    shifts_without_rule_clean_candidates: groupsWithoutAutoAssignableCandidates.length,
    shifts_without_any_manager_ask: groupsWithoutAnyManagerAsk.length,
  },

  candidate_groups: repairCandidateGroups,

  manager_next_steps: [
    "Review auto-assignable candidates first, if any.",
    "For shifts with no auto-assignable candidate, use manager-ask options: Patrick wildcard, full-weekend exception, or extra-shift consent.",
    "Do not auto-assign Core Team full weekends. Ask the person first and document the exception.",
    "Ask Lilly for consent before assigning above target/capacity.",
    "Patrick should remain a wildcard manager ask unless he is added as active staff in Supabase.",
    "After any manual draft change, re-run validation before publishing.",
  ],
};

return [
  {
    json: {
      ...input,

      repair_plan: repairPlan,

      validation: {
        ...validation,
        ready_for_commit: false,
        requires_human_review: true,
      },

      repair_candidates_generated_at: new Date().toISOString(),
    },
  },
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one validation/repair item, received ${items.length}.`);
}

const input = items[0].json;

const generationRunId = input.generation_run_id;
const periodId = input.period_id;
const validation = input.validation ?? {};
const repairPlan = input.repair_plan ?? {};
const draftPlan = input.draft_plan ?? {};
const plannerAgentReview = input.planner_agent_review ?? {};

if (!generationRunId) throw new Error("Missing generation_run_id.");
if (!periodId) throw new Error("Missing period_id.");

const hardViolations = Array.isArray(validation.hard_rule_violations)
  ? validation.hard_rule_violations
  : [];

const softWarnings = Array.isArray(validation.soft_rule_warnings)
  ? validation.soft_rule_warnings
  : [];

const humanReviewFlags = Array.isArray(validation.human_review_flags)
  ? validation.human_review_flags
  : [];

const candidateGroups = Array.isArray(repairPlan.candidate_groups)
  ? repairPlan.candidate_groups
  : [];

const unfilledShifts = Array.isArray(draftPlan.unfilled_shifts)
  ? draftPlan.unfilled_shifts
  : [];

function uniqueBy(array, keyFn) {
  const seen = new Set();
  const result = [];

  for (const item of array) {
    const key = keyFn(item);
    if (seen.has(key)) continue;

    seen.add(key);
    result.push(item);
  }

  return result;
}

const unfilledBlockingIssues = hardViolations
  .filter((violation) => violation.type === "mandatory_shift_underfilled")
  .map((violation) => {
    const details = violation.details ?? {};

    return {
      type: violation.type,
      message: violation.message,
      shift_id: details.shift_id ?? null,
      shift_date: details.shift_date ?? null,
      shift_type: details.shift_type ?? null,
      missing_count: details.missing_count ?? null,
      reason: details.reason ?? null,
    };
  });

const uniqueUnfilledBlockingIssues = uniqueBy(
  unfilledBlockingIssues,
  (issue) => issue.shift_id || `${issue.shift_date}:${issue.shift_type}`
);

const otherHardIssues = hardViolations
  .filter((violation) => violation.type !== "mandatory_shift_underfilled")
  .map((violation) => ({
    type: violation.type,
    message: violation.message,
    details: violation.details ?? {},
  }));

const repairOptions = candidateGroups.map((group) => {
  const autoAssignableCandidates = Array.isArray(group.auto_assignable_candidates)
    ? group.auto_assignable_candidates
    : Array.isArray(group.recommended_candidates)
      ? group.recommended_candidates
      : [];

  const managerAskCandidates = Array.isArray(group.manager_ask_candidates)
    ? group.manager_ask_candidates
    : [];

  const blockedCandidates = Array.isArray(group.blocked_candidates)
    ? group.blocked_candidates
    : [];

  return {
    shift_id: group.shift_id,
    shift_date: group.shift_date,
    shift_type: group.shift_type,
    missing_count: group.missing_count,

    has_rule_clean_candidate: Boolean(group.has_rule_clean_candidate),

    auto_assignable_candidate_count: autoAssignableCandidates.length,
    recommended_candidate_count: autoAssignableCandidates.length,

    manager_ask_candidate_count: managerAskCandidates.length,

    auto_assignable_candidates: autoAssignableCandidates.map((candidate) => ({
      staff_id: candidate.staff_id,
      staff_name: candidate.staff_name,
      work_role: candidate.work_role,
      scheduling_rule_role: candidate.scheduling_rule_role,
      training_phase: candidate.training_phase,
      score: candidate.score,
      warnings: candidate.warnings ?? [],
      reasons: candidate.reasons ?? [],
    })),

    manager_ask_candidates: managerAskCandidates.map((candidate) => ({
      candidate_type: candidate.candidate_type,
      staff_id: candidate.staff_id ?? null,
      staff_name: candidate.staff_name ?? candidate.candidate_name ?? null,
      work_role: candidate.work_role ?? null,
      scheduling_rule_role: candidate.scheduling_rule_role ?? null,
      training_phase: candidate.training_phase ?? null,
      reason: candidate.reason,
      manager_ask_reasons: candidate.manager_ask_reasons ?? [],
      requires_manager_approval: candidate.requires_manager_approval ?? true,
      requires_staff_consent: candidate.requires_staff_consent ?? true,
      can_auto_assign: false,
      blockers: candidate.blockers ?? [],
      warnings: candidate.warnings ?? [],
      note: candidate.note ?? null,
    })),

    top_blocked_candidates: blockedCandidates.slice(0, 4).map((candidate) => ({
      staff_id: candidate.staff_id,
      staff_name: candidate.staff_name,
      work_role: candidate.work_role,
      scheduling_rule_role: candidate.scheduling_rule_role,
      training_phase: candidate.training_phase,
      blockers: candidate.blockers ?? [],
      warnings: candidate.warnings ?? [],
    })),

    recommendation: group.recommendation,
  };
});

let status = "ready";

if (validation.ready_for_commit === false || validation.is_valid === false) {
  status = "blocked";
} else if (validation.requires_human_review === true) {
  status = "needs_review";
}

const headline =
  status === "blocked"
    ? "Schedule needs manager review before publishing"
    : status === "needs_review"
      ? "Schedule is valid but still needs manager review"
      : "Schedule is ready to publish";

const nextActions = [];

if (uniqueUnfilledBlockingIssues.length > 0) {
  nextActions.push(
    "Review the unfilled mandatory shifts and choose either an auto-assignable candidate, manager-ask option, or manual override."
  );
}

if (repairOptions.some((option) => option.manager_ask_candidate_count > 0)) {
  nextActions.push(
    "Use manager-ask options where needed: Patrick wildcard, full-weekend exception, or extra-shift consent."
  );
}

if (repairOptions.some((option) => option.manager_ask_candidates?.some((candidate) => candidate.staff_name === "Patrick"))) {
  nextActions.push(
    "Patrick is a wildcard suggestion only unless added as active staff in Supabase."
  );
}

if (repairOptions.some((option) => option.manager_ask_candidates?.some((candidate) => candidate.staff_name === "Lilly"))) {
  nextActions.push(
    "Ask Lilly for explicit consent before adding extra shifts above her target/capacity."
  );
}

if (softWarnings.some((warning) => warning.type === "weekly_minimum_not_met" || warning.type === "below_period_target")) {
  nextActions.push(
    "Review staff who are below minimum/target before leaving shifts uncovered or overloading others."
  );
}

if (softWarnings.some((warning) => warning.type === "fragmented_work_pattern")) {
  nextActions.push(
    "Where possible, adjust the draft toward grouped/consecutive workdays instead of fragmented work-off-work patterns."
  );
}

if (softWarnings.some((warning) => warning.type === "budget_capacity_unused_with_unfilled_shifts")) {
  nextActions.push(
    "There appears to be budget/capacity available while shifts remain uncovered; consider using available capacity before accepting gaps."
  );
}

if (humanReviewFlags.length > 0) {
  nextActions.push(
    "Review human-review flags from the planner agent before approving or overriding the schedule."
  );
}

if (nextActions.length === 0 && status === "ready") {
  nextActions.push("Manager can proceed to the draft commit/publish step.");
}

const managerReview = {
  status,
  headline,

  ready_for_commit: Boolean(validation.ready_for_commit),
  requires_human_review: Boolean(validation.requires_human_review),

  summary: {
    assignment_count: validation.summary?.assignment_count ?? null,
    unfilled_shift_count:
      validation.summary?.unfilled_shift_count ??
      unfilledShifts.length,
    hard_rule_violation_count:
      validation.summary?.hard_rule_violation_count ??
      hardViolations.length,
    soft_rule_warning_count:
      validation.summary?.soft_rule_warning_count ??
      softWarnings.length,
    human_review_flag_count:
      validation.summary?.human_review_flag_count ??
      humanReviewFlags.length,

    repair_candidate_group_count:
      repairPlan.summary?.repair_candidate_group_count ??
      candidateGroups.length,

    total_auto_assignable_candidate_count:
      repairPlan.summary?.total_auto_assignable_candidate_count ??
      repairPlan.summary?.total_recommended_candidate_count ??
      null,

    total_recommended_candidate_count:
      repairPlan.summary?.total_recommended_candidate_count ?? null,

    total_manager_ask_candidate_count:
      repairPlan.summary?.total_manager_ask_candidate_count ?? null,

    shifts_without_rule_clean_candidates:
      repairPlan.summary?.shifts_without_rule_clean_candidates ?? null,

    shifts_without_any_manager_ask:
      repairPlan.summary?.shifts_without_any_manager_ask ?? null,

    estimated_draft_labor_cost_eur:
      validation.summary?.estimated_draft_labor_cost_eur ?? null,

    monthly_staff_budget_eur:
      validation.summary?.monthly_staff_budget_eur ?? null,

    estimated_budget_remaining_eur:
      validation.summary?.estimated_budget_remaining_eur ?? null,

    draft_assignments_saved:
      validation.summary?.draft_assignments_saved ?? null,

    draft_assignments_inserted_count:
      validation.summary?.draft_assignments_inserted_count ?? null,
  },

  blocking_issues: [
    ...uniqueUnfilledBlockingIssues,
    ...otherHardIssues,
  ],

  repair_options: repairOptions,

  soft_warnings: softWarnings.map((warning) => ({
    type: warning.type,
    message: warning.message,
    details: warning.details ?? {},
  })),

  human_review_flags: humanReviewFlags.map((flag) => ({
    type: flag.type,
    severity: flag.severity,
    message: flag.message,
    details: flag.details ?? {},
  })),

  planner_agent_summary: plannerAgentReview.agent_summary ?? null,
  planner_agent_risk_level: plannerAgentReview.overall_risk_level ?? null,

  next_actions: [...new Set(nextActions)],
};

return [
  {
    json: {
      generation_run_id: generationRunId,
      period_id: periodId,

      manager_review: managerReview,

      validation_summary: validation.summary ?? null,
      repair_summary: repairPlan.summary ?? null,

      ready_for_commit: managerReview.ready_for_commit,
      requires_human_review: managerReview.requires_human_review,

      manager_review_generated_at: new Date().toISOString(),
    },
  },
];
